  "contacts": [
    {
      "contactId": "8de16b15-0723-5609-917c-df5bc64b9277",
      "name": "George Eliadis",
      "roleLabel": "Economic Buyer - Co-Founder & CEO",
      "overview": "George Eliadis is Probook's Co-Founder & CEO and previously worked as a contractor at A2Z Exterior Pressure Washing. He has publicly discussed Probook's $40M funding and the transition away from founder-led sales, and a verified work email is available.",
      "howToOpen": [
        {
          "line": "You wrote, “Today, we're announcing $40M in funding from Sequoia and Andreessen Horowitz to solve a problem I faced in my own business.” What is the next operating constraint that funding needs to remove?",
          "hook": "Today, we're announcing $40M in funding from Sequoia and Andreessen Horowitz to solve a problem I faced in my own business.",
          "sourceUrl": "https://www.linkedin.com/posts/george-eliadis_today-were-announcing-40m-in-funding-from-activity-7475172924774293504-mVOB"
        },
        {
          "line": "You said, “Being stuck in founder-led sales isn't a flex. I wish I realized that sooner.” How are you building the next version of the sales motion?",
          "hook": "Being stuck in founder-led sales isn't a flex. I wish I realized that sooner",
          "sourceUrl": "https://www.linkedin.com/posts/george-eliadis_until-december-our-sales-team-was-just-activity-7441840906384683008-3s7v"
        },
        {
          "line": "You’ve personally met Probook customers and run every demo; what are you now trying to preserve as the team scales?",
          "hook": "I've personally met pretty much every Probook customer, run every demo, and traveled across the US to visit almost every shop.",
          "sourceUrl": "https://www.linkedin.com/posts/george-eliadis_until-december-our-sales-team-was-just-activity-7441840906384683008-3s7v"
        }
      ]
    },
    {
      "contactId": "f31ccd75-f376-528f-8b6c-f2f823a60e56",
      "name": "Mark Hoffman",
      "roleLabel": "Economic Buyer - Chief Revenue Officer",
      "overview": "Mark Hoffman is Probook's Chief Revenue Officer, joining after serving as Chief Sales Officer at Tennr and holding sales leadership roles at VTS, Hightower, and ZocDoc. His public posts focus on building the GTM team and Probook's $40M raise, and a verified work email is available.",
      "howToOpen": [
        {
          "line": "You wrote that the GTM team is “inching up towards 20 now, with many more to go.” What has to be in place before the next hiring wave?",
          "hook": "The GTM team is inching up towards 20 now, with many more to go.",
          "sourceUrl": "https://www.linkedin.com/posts/mark-hoffman-582a5741_today-is-a-big-day-at-probook-were-announcing-activity-7475232474495725568--2KU"
        },
        {
          "line": "You called the first four months “far less easy” and said there are big problems every day. Which revenue problem is most urgent to solve?",
          "hook": "The first 4 months have been far less easy, which is exactly how it should be. Big problems every day, and some of the smartest, most thoughtful people I've ever worked with showing up to solve them. The GTM team is inching up towards 20 now, with many more to go.",
          "sourceUrl": "https://www.linkedin.com/posts/mark-hoffman-582a5741_today-is-a-big-day-at-probook-were-announcing-activity-7475232474495725568--2KU"
        }
      ]
    },
    {
      "contactId": "0c49f3eb-9f51-579b-99f7-6acb965af754",
      "name": "Kate Blumberg",
      "roleLabel": "Champion - Director of Growth",
      "overview": "Kate Blumberg is Probook's Director of Growth, responsible for leading growth and building the marketing organization. She joined after serving as Director of Demand Generation at BuildOps and holding growth and demand-generation roles at Middesk, SafeGraph, and Survata; a verified work email is available.",
      "howToOpen": [
        {
          "line": "You shared that you joined Probook “to lead growth and build out the marketing organization.” What is the first system you are putting in place?",
          "hook": "I’m excited to share that I’ve joined Probook to lead growth and build out the marketing organization",
          "sourceUrl": "https://www.linkedin.com/posts/kibrady12_im-excited-to-share-that-ive-joined-probook-activity-7475235473679077376-nv9z"
        },
        {
          "line": "At BuildOps, you focused on a demand-generation engine that delivered for sales across inbound, ABM, events, lifecycle, and paid. Which part carries over to Probook first?",
          "hook": "When I joined BuildOps, it was to join a high-performing, revenue-obsessed team where I could focus on one thing: building a demand generation engine that delivered for sales… hiring and leading a team, scaling programs across inbound, ABM, events, lifecycle, and paid… creating systems, scaling teams, sharpening positioning, and helping turn momentum into revenue.",
          "sourceUrl": "https://www.linkedin.com/posts/kibrady12_after-two-years-at-buildops-i-activity-7459629371444703232-esk_"
        }
      ]
    },
    {
      "contactId": "61006812-713c-5564-8c38-16620cbcc0b3",
      "name": "Aaron Churba",
      "roleLabel": "Champion - Director of Sales & Development",
      "overview": "Aaron Churba is Probook's Director of Sales & Development and is currently leading a team of 5 sellers. He previously held sales leadership roles at Bite, Zip Security, and Electric, and a verified work email is available.",
      "howToOpen": [
        {
          "line": "You’re “currently leading a team of 5 sellers and counting.” What does the next seller need to be able to do independently?",
          "hook": "Currently leading a team of 5 sellers and counting.",
          "sourceUrl": "https://www.linkedin.com/in/aaronloganchurba"
        },
        {
          "line": "You’re focused on helping businesses discover Probook and building the GTM organization. Where is the team feeling the most friction today?",
          "hook": "helping more businesses discover Probook, building a world-class GTM organization, and contributing to the next stage of growth.",
          "sourceUrl": "https://www.linkedin.com/in/aaronloganchurba"
        },
        {
          "line": "You wrote that prospects buy from people they like, relate to, or aspire to emulate. How does that shape your sales coaching at Probook?",
          "hook": "In my ~10 year journey in SaaS sales, one key lesson stands out: prospects buy from people they like, relate to, or aspire to emulate.",
          "sourceUrl": "https://www.linkedin.com/posts/aaronloganchurba_saassales-salesleadership-relationshipbuilding-activity-7211858644965978113-UIvD"
        }
      ]
    },
    {
      "contactId": "f4ec4553-7a98-5f74-8e61-2e445319374b",
      "name": "Lewis Zhang",
      "roleLabel": "Technical Evaluator - Co-Founder / CTO",
      "overview": "Lewis Zhang is Probook's Co-Founder / CTO and previously worked as a Senior ML Engineer at Roblox. His background also includes research at Berkeley Artificial Intelligence Research and engineering internships at Confluent, Rubrik, Tesla, and Intel; a verified work email is available.",
      "howToOpen": [
        {
          "line": "You said you’re “way better at math” and planned to share the small wins. What technical win is most important for Probook's next stage?",
          "hook": "I'm certainly not the best writer (way better at math) but I am going to start to be more active on LinkedIn and share the small wins.",
          "sourceUrl": "https://www.linkedin.com/posts/lewisfzhang_im-certainly-not-the-best-writer-way-better-activity-7387118180609085442-UJ-d"
        },
        {
          "line": "Your stated interests include scalable data and ML systems and reliable engineering workflows. Where is reliability hardest as Probook scales?",
          "hook": "contributing to open source project Scalabel.ai, a web annotation tool for autonomous driving datasets",
          "sourceUrl": "https://www.linkedin.com/in/lewisfzhang"
        }
      ]
    }
